import flask
from flask import request, jsonify
import subprocess
import os
import re
import hashlib

app = flask.Flask(__name__)

# Configuration
ALLOWED_COMMANDS = ['status', 'info', 'version', 'health']
AUDIT_LOG = '/var/log/app/commands.log'

def validate_input(user_input):
    """Basic input validation - alphanumeric and limited special chars"""
    # Allow alphanumeric, dots, hyphens, underscores, forward slashes
    pattern = r'^[a-zA-Z0-9._/\-]+$'
    if not re.match(pattern, user_input):
        return False
    if len(user_input) > 256:
        return False
    return True

def get_auth_token():
    """Extract bearer token from request"""
    auth_header = request.headers.get('Authorization', '')
    if auth_header.startswith('Bearer '):
        return auth_header[7:]
    return None

def verify_token(token):
    """Verify token against known service accounts"""
    if not token:
        return False
    known_hashes = os.environ.get('SERVICE_TOKEN_HASHES', '').split(',')
    token_hash = hashlib.sha256(token.encode()).hexdigest()
    return token_hash in known_hashes

@app.route('/api/v1/diagnostic', methods=['POST'])
def run_diagnostic():
    """Run diagnostic commands on the container"""
    token = get_auth_token()
    if not verify_token(token):
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    if not data or 'command' not in data:
        return jsonify({'error': 'missing command field'}), 400

    cmd_name = data['command']
    cmd_args = data.get('args', '')

    if cmd_name not in ALLOWED_COMMANDS:
        return jsonify({'error': f'command not in allowlist: {cmd_name}'}), 403

    # Build the diagnostic command
    # The base commands are safe, but args are user-controlled
    if cmd_args:
        if not validate_input(cmd_args):
            return jsonify({'error': 'invalid characters in args'}), 400
        full_command = f"/opt/diagnostics/{cmd_name} {cmd_args}"
    else:
        full_command = f"/opt/diagnostics/{cmd_name}"

    try:
        # Log the command for audit
        with open(AUDIT_LOG, 'a') as f:
            f.write(f"{request.remote_addr} | {cmd_name} | {cmd_args}\n")

        result = subprocess.run(
            full_command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=10,
            env={'PATH': '/opt/diagnostics:/usr/bin', 'HOME': '/tmp'}
        )

        return jsonify({
            'stdout': result.stdout,
            'stderr': result.stderr,
            'returncode': result.returncode
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'command timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/health', methods=['GET'])
def health_check():
    return jsonify({'status': 'ok'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
